/**
 * Shot specs the decks share. A shot is captured from a running page during
 * the render, so it is always the product as it is today.
 */
import { readFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..', '..')

/**
 * The compiled output of a runnable doc snippet
 * (examples/src/doc-snippets/<id>.svelte, generated by
 * tools/build-doc-snippets.mjs), mounted by the recording stage. Pair it with
 * `snippetSource(id)` and the code slide and the result slide are the same
 * file, the guarantee the course videos rely on.
 */
export function stageSnippet(id, { width = 560, selector = '.br-page-snippet .sv-grid-root', css = '', trim = true } = {}) {
  return {
    server: 'gallery',
    path: '/stage.html',
    viewport: { width: 1280, height: 720 },
    async setup(page) {
      await page.waitForFunction(() => !!window.__stage, null, { timeout: 30_000 })
      await page.evaluate(async (sid) => {
        await window.__stage.show('browser')
        await window.__stage.browser.snippet(sid, { loadMs: 50 })
      }, id)
      await page.waitForSelector('.br-page-snippet table, .br-page-snippet [data-svgrid-row]', { timeout: 30_000 })
    },
    // The stage lays a snippet out across a 1280px browser frame. A three-
    // column grid uses a third of that, and on a 1080px slide the rest is
    // empty frame around unreadable text. Narrow the page to the grid so the
    // crop scales up to a size a phone can read.
    css: `.br-page-snippet { flex: 0 0 auto !important; width: ${width}px; }
      .br-page-snippet .sv-grid-root { width: ${width - 52}px; } ${css}`,
    selector,
    trim,
    scale: 3,
  }
}

/** A runnable doc snippet's source, verbatim. */
export function snippetSource(id) {
  return readFileSync(join(ROOT, 'examples', 'src', 'doc-snippets', `${id}.svelte`), 'utf8').replace(/\r\n/g, '\n').trimEnd()
}

/** A gallery demo, chrome hidden, cropped to its content. */
export function demo(id, { width = 1000, height = 1100, selector = '.demo-page > main', setup, waitFor = '[data-svgrid-row]', trim = false, css } = {}) {
  return { server: 'gallery', path: `/#/${id}`, viewport: { width, height }, selector, setup, waitFor, trim, css }
}
